from pathlib import Path
import re

P=Path('custom_components/s8_omni/frontend/s8-omni-panel.js')
t=P.read_text(encoding='utf-8')
t=t.replace('const UI_VERSION = "v0.7.5";','const UI_VERSION = "v0.7.6";',1)
t=re.sub(r'function productArtData\(mode\) \{.*?\n\}', 'function productArtUrl(mode) {\n  const safeMode = mode === "dock" ? "dock" : "clean";\n  return `/s8_omni/product-art/${safeMode}.jpg?v=${encodeURIComponent(UI_VERSION)}`;\n}', t, count=1, flags=re.S)
t=t.replace('if (["charging", "charged"].includes(snap.robot)) return "На базе";\n    return this._label(MODE_LABELS, snap.mode, "Нет данных");','return this._label(MODE_LABELS, snap.mode, "Нет данных");',1)

start=t.index('  _heroHint(snap) {'); end=t.index('\n  _hero() {',start)
t=t[:start]+'''  _heroHint(snap) {\n    if (snap.connection === "disconnected") return "Нет актуальной локальной телеметрии";\n    if (snap.connection === "unknown") return "Текущая связь с устройством не подтверждена";\n    const ops = new Set(snap.stationOperations || []);\n    if (ops.has("drying") || snap.station === "drying") return "Робот на станции и сушится";\n    if (ops.has("roller_cleaning") || snap.station === "roller_cleaning") return "Станция промывает моющий модуль";\n    if (ops.has("dust_collection") || snap.station === "dust_collection") return "Станция выполняет сбор пыли";\n    if (snap.robot === "charged") return "Робот на станции, заряд завершён";\n    if (snap.robot === "charging") return "Робот на станции и заряжается";\n    if (["cleaning", "zone_cleaning", "room_cleaning"].includes(snap.composite)) return "Выполняется уборка";\n    if (snap.composite === "returning_to_dock") return "Робот возвращается на станцию";\n    return "Робот и станция работают как единая система";\n  }\n'''+t[end:]

start=t.index('  _hero() {'); end=t.index('\n  _quickActions() {',start)
hero='''  _hero() {\n    const snap=this._snapshot(), connection=this._connectionLabel(), ops=new Set(snap.stationOperations||[]);\n    const compositeLabel=snap.connection==="disconnected"?"Нет связи":snap.connection==="unknown"?"Связь не подтверждена":this._label(COMPOSITE_LABELS,snap.composite,"Нет данных");\n    const wash=!snap.unreliable&&(ops.has("roller_cleaning")||snap.station==="roller_cleaning"), dust=!snap.unreliable&&(ops.has("dust_collection")||snap.station==="dust_collection"), dry=!snap.unreliable&&(ops.has("drying")||snap.station==="drying");\n    const charging=!snap.unreliable&&snap.robot==="charging", charged=!snap.unreliable&&snap.robot==="charged", docked=!snap.unreliable&&snap.onDock===true, chargeActive=charging||charged||docked;\n    const artMode=chargeActive||wash||dust||dry?"dock":"clean", battery=snap.battery===null?"—":`${Math.round(snap.battery)}%`, age=snap.age===null?"—":this._formatDuration(snap.age), mode=this._modeLabel(snap);\n    const unknown=snap.unreliable?"Нет данных":"Не контрол.", dustState=snap.unreliable?"Нет данных":dust?"Работает":"Ожидание", dryState=snap.unreliable?"Нет данных":dry?"Вкл.":"Выкл.", chargeState=snap.unreliable?"Нет данных":charging?"Идёт":charged?"Завершён":docked?"На базе":"Нет";\n    return `<section class="card hero" data-more="composite_status"><div class="hero-top"><div><span class="eyebrow">Состояние</span><h1>${escapeHtml(compositeLabel)}</h1><p class="hero-hint">${escapeHtml(this._heroHint(snap))}</p></div><div class="connection-badge ${connection!=="Локально"?"bad":""}"><i class="dot"></i>${escapeHtml(connection)}</div></div><div class="omni-scene"><div class="omni-art ${snap.unreliable?"muted":""}"><img class="product-art" src="${productArtUrl(artMode)}" alt="S8 OMNI robot and station" />${snap.connected?'<div class="scene-local"><ha-icon icon="mdi:wifi"></ha-icon><span>Локально</span></div>':""}</div><div class="omni-legend"><div class="legend-row clean-water"><ha-icon icon="mdi:water"></ha-icon><span class="legend-copy"><strong>Чистая вода</strong><small>${unknown}</small></span></div><div class="legend-row dirty-water"><ha-icon icon="mdi:water-opacity"></ha-icon><span class="legend-copy"><strong>Грязная вода</strong><small>${unknown}</small></span></div><div class="legend-row dust ${dust?"active":""}"><ha-icon icon="mdi:delete-outline"></ha-icon><span class="legend-copy"><strong>Пыль/мешок</strong><small>${dustState}</small></span></div><div class="legend-row dry ${dry?"active":""}"><ha-icon icon="mdi:weather-windy"></ha-icon><span class="legend-copy"><strong>Тёплый воздух</strong><small>${dryState}</small></span></div><div class="legend-row charge ${chargeActive?"active":""}"><ha-icon icon="${charging?"mdi:battery-charging":"mdi:flash"}"></ha-icon><span class="legend-copy"><strong>Зарядка</strong><small>${chargeState}</small></span></div></div></div><div class="hero-metrics"><div data-more="battery"><ha-icon class="metric-icon battery" icon="mdi:battery-medium"></ha-icon><span>АКБ</span><strong>${battery}</strong><small>Текущий заряд</small><div class="battery-bar"><i style="width:${snap.battery??0}%"></i></div></div><div data-more="mode"><ha-icon class="metric-icon mode" icon="mdi:fan"></ha-icon><span>Режим</span><strong>${escapeHtml(mode)}</strong><small>${mode==="Smart"?"Автовыбор":"Профиль уборки"}</small></div><div data-more="telemetry_age"><ha-icon class="metric-icon telemetry" icon="mdi:signal-cellular-3"></ha-icon><span>Телеметрия</span><strong>${escapeHtml(age)}</strong><small>Последнее обновление</small></div></div></section>`;\n  }\n'''
t=t[:start]+hero+t[end:]

start=t.index('  _quickActions() {'); end=t.index('\n  _overview() {',start)
quick='''  _quickActions() {\n    const snap=this._snapshot(), vacuum=snap.vacuum, available=snap.connected&&this._available(vacuum), cleaning=vacuum?.state==="cleaning", paused=vacuum?.state==="paused", docked=snap.onDock===true||["charging","charged"].includes(snap.robot);\n    const startClass=cleaning?"action running":docked?"action ready":"action primary", pauseClass=cleaning?"action primary":"action", homeClass=docked?"action primary running":"action", startTitle=paused?"Продолжить":"Уборка";\n    return `<div class="quick-actions"><button class="${startClass}" data-action="start" ${available&&!cleaning?"":"disabled"}><span class="action-icon"><ha-icon icon="${cleaning?"mdi:robot-vacuum":"mdi:play"}"></ha-icon></span><strong>${startTitle}</strong><span class="action-sub">${cleaning?"Идёт":paused?"Возобновить":"Smart"}</span></button><button class="${pauseClass}" data-action="pause" ${available&&cleaning?"":"disabled"}><span class="action-icon"><ha-icon icon="mdi:pause"></ha-icon></span><strong>Пауза</strong><span class="action-sub">${cleaning?"Приостановить":"Недоступно"}</span></button><button class="${homeClass}" data-action="home" ${available&&!docked?"":"disabled"}><span class="action-icon"><ha-icon icon="mdi:home"></ha-icon></span><strong>Домой</strong><span class="action-sub">${docked?"На базе":"На станцию"}</span></button></div>`;\n  }\n'''
t=t[:start]+quick+t[end:]

start=t.index('  _overview() {'); end=t.index('\n  _cleaning() {',start)
over='''  _overview() {\n    const snap=this._snapshot(), robot=snap.unreliable?"Нет данных":this._label(ROBOT_LABELS,snap.robot,"Нет данных"), stationRaw=snap.unreliable?"Нет данных":this._label(STATION_LABELS,snap.station,"Нет данных"), station=snap.station==="idle"&&!snap.unreliable?"Готова":stationRaw;\n    const robotContext=snap.unreliable?"Нет данных":snap.onDock===true?"На базе":snap.onDock===false?"В работе":"Позиция неизвестна", operation=snap.unreliable?"Нет данных":snap.stationOperations.length?snap.stationOperations.map(x=>STATION_OPERATION_LABELS[x]||x).join(" · "):snap.missingStationDps.length?"Часть данных":"В ожидании";\n    return `<div>${this._hero()}${this._trustBanner(snap)}${this._quickActions()}<section class="card statuses-card"><div class="statuses-head"><h2>Статусы</h2><button type="button" data-view="station">Все <ha-icon icon="mdi:chevron-right"></ha-icon></button></div><div class="status-grid"><button class="status-card good" data-more="robot_status" type="button"><span class="status-icon robot"><ha-icon icon="mdi:robot-vacuum"></ha-icon></span><strong>Робот</strong><b>${escapeHtml(robot)}</b><span class="meta">${escapeHtml(robotContext)}</span></button><button class="status-card good" data-more="station_status" type="button"><span class="status-icon station"><ha-icon icon="mdi:home-automation"></ha-icon></span><strong>Станция</strong><b>${escapeHtml(station)}</b><span class="meta">${escapeHtml(operation)}</span></button><div class="status-card neutral"><span class="status-icon water"><ha-icon icon="mdi:cup-water"></ha-icon></span><strong>Чистая вода</strong><b>—</b><span class="meta">Нет датчика уровня</span></div><div class="status-card neutral"><span class="status-icon dustbin"><ha-icon icon="mdi:delete-outline"></ha-icon></span><strong>Пылесборник</strong><b>—</b><span class="meta">Нет датчика заполнения</span></div></div></section></div>`;\n  }\n'''
t=t[:start]+over+t[end:]

css='''.content{padding-bottom:calc(118px + env(safe-area-inset-bottom))}.omni-scene{height:236px}.omni-art{left:0;top:0;bottom:0;width:75%;overflow:hidden;border-radius:21px}.product-art{border-radius:21px;filter:none}.scene-local{position:absolute;left:12px;top:12px;display:inline-flex;align-items:center;gap:6px;min-height:30px;padding:0 10px;border-radius:999px;background:rgba(225,242,255,.94);color:#087cc0;font-size:11px;font-weight:800;box-shadow:0 4px 12px rgba(20,86,120,.08)}.scene-local ha-icon{--mdc-icon-size:17px}.omni-legend{width:31%;gap:5px;padding:8px}.legend-row{grid-template-columns:20px minmax(0,1fr);min-height:35px;padding:4px 5px}.legend-copy{min-width:0}.legend-copy strong,.legend-copy small{display:block;overflow:hidden;text-overflow:ellipsis}.legend-copy strong{font-size:10px;white-space:nowrap}.legend-copy small{font-size:9px;font-weight:700;color:var(--secondary-text-color);margin-top:2px;white-space:nowrap}.legend-row.clean-water ha-icon{color:#139ee0}.legend-row.dirty-water ha-icon{color:#6c7479}.legend-row.dry.active{background:#fff3e9;color:#a85d22}.legend-row.charge.active{background:#edf9f0;color:#2e914b}.hero-metrics>div{position:relative;min-height:82px;padding:10px 10px 9px 44px}.hero-metrics .metric-icon{position:absolute;left:10px;top:18px;--mdc-icon-size:27px}.metric-icon.battery{color:#48b94f}.metric-icon.mode{color:var(--primary-color)}.metric-icon.telemetry{color:#43b75a}.hero-metrics small{display:block;margin-top:4px;color:var(--secondary-text-color);font-size:9px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.battery-bar{margin-left:-34px}.action.ready{background:color-mix(in srgb,var(--primary-color) 9%,var(--card-background-color));color:var(--primary-color)}.statuses-head{display:flex;align-items:center;justify-content:space-between;margin-bottom:12px}.statuses-head h2{font-size:24px;line-height:1}.statuses-head button{border:0;background:transparent;color:var(--secondary-text-color);display:flex;align-items:center;gap:2px;font-size:12px}.statuses-head ha-icon{--mdc-icon-size:18px}.status-card.neutral b{color:var(--secondary-text-color)}.status-icon.water{color:#159fdf}.status-icon.dustbin{color:#697278}@media(max-width:430px){.omni-scene{height:228px}.omni-art{width:73%}.omni-legend{width:32%;right:6px}.hero-metrics>div{padding-left:39px}.hero-metrics .metric-icon{left:8px;--mdc-icon-size:24px}.status-card span.meta{white-space:normal;min-height:22px}}'''
t=t.replace('      @keyframes spin{to{transform:rotate(360deg)}}', '      '+css+'\n      @keyframes spin{to{transform:rotate(360deg)}}',1)
P.write_text(t,encoding='utf-8')
